mapper.select:
SELECT id, user_id, image_url, latex_result, confidence, feedback, created_at, updated_at
FROM recognition_history
WHERE id = #{id}

mapper.update:
UPDATE recognition_history
SET feedback = #{feedback}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, user_id, image_url, latex_result, confidence, feedback, created_at, updated_at
FROM recognition_history
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM recognition_history
WHERE user_id = #{userId}
